  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export type StepKind = "move" | "turn" | "pen" | "style";

/** One executed primitive command, used by the UI for stepping and animation. */
export interface StepEvent {
  kind: StepKind;
  tok: Token;
  before: Pose;
  after: Pose;
  segment: Segment | null;
}

export function initialPose(): Pose {
  return {
    pos: [0, 0, 0],
    heading: [0, 1, 0],
    right: [1, 0, 0],
    up: [0, 0, 1],
    penDown: true,
    color: DEFAULT_COLOR,
    width: DEFAULT_WIDTH,
  };
