await page.click("#mode3d"); await page.waitForTimeout(1500);
await page.click("#runBtn"); await page.waitForTimeout(1500);
console.log("PITCH3D:", await status());
// examples
for (const ex of ["szescian", "sprezyna", "drzewo", "kwiat", "domek", "gwiazda"]) {
  await page.selectOption("#examples", ex); await page.waitForTimeout(ex === "kwiat" ? 6000 : 2500);
  await page.screenshot({ path: `/tmp/ex-${ex}.png` });
  console.log("EX", ex, await status());
}
// help
await page.click("#helpBtn"); await page.waitForTimeout(200);
await page.screenshot({ path: "/tmp/shot-help.png" });
await page.keyboard.press("Escape");
